(function () {
  'use strict';
  const E = window.MesaEngine;
  const C = window.MesaCoach;
  let aiConnection={status:"idle"}, aiBusy=false;
  const aiNotes=new Map(), localAnalyses=new Map();
  const app = document.getElementById('app');
  const modal = document.getElementById('modal');
  const KEY = 'mesa10-state-v1';
  let storageOK = true, view = 'train', chartPosition = 'BTN', chartContext='cash', chartSelected = 'AKs', reviewedSession = null, toastTimer, lastDealKey = '';
  const safe = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const bb = value => Number(value).toLocaleString('pt-BR',{maximumFractionDigits:2});
  const pct = value => Math.round(value * 100) + '%';
  const words = {fold:'Desistir',call:'Pagar',raise:'Aumentar',shove:'All-in',check:'Dar check',bet:'Apostar',hero:'Você vence',villain:'Adversário vence',tie:'Empate'};
  function fresh() { const opponents=E.createOpponents(); return {opponents,version:1,prefs:{mode:'balanced',atmosphere:'mixed'},profile:{xp:0,answered:0,correct:0,unassisted:0,unassistedCorrect:0,streak:0,bestStreak:0,sessions:0},history:[],session:E.createSession({opponents})}; }
  function load() {
    try {
      const raw=localStorage.getItem(KEY);
      if(raw){const s=JSON.parse(raw);if(s.version===1&&s.session?.hands?.length===10&&s.profile&&Array.isArray(s.history)){
        for(const h of s.session.hands){E.validateCards(h.kind==='omaha'?[...h.hero,...h.villain,...h.board]:[...h.cards,...h.villainCards,...h.board],h.kind==='omaha'?13:9);}
        return s;
      }}
    } catch (_) { storageOK=false; }
    return fresh();
  }
  let state=load();
  state.opponents ||= E.createOpponents();
  state.prefs ||= {mode:'balanced',atmosphere:'mixed'};
  state.prefs.atmosphere ||= 'mixed';
  const cashUI=window.createCashUI({state,save,render,openModal,toast,cards,safe,bb,nav:navigate});
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(_){storageOK=false;}return storageOK;}
  function current(){return state.session.hands[state.session.current];}
  function stats(session){const decisions=session.hands.flatMap(h=>h.decisions||[]), solo=decisions.filter(d=>!d.assisted);return {total:decisions.length,correct:decisions.filter(d=>d.correct).length,assisted:decisions.filter(d=>d.assisted).length,solo:solo.length,soloCorrect:solo.filter(d=>d.correct).length,accuracy:solo.length?Math.round(solo.filter(d=>d.correct).length/solo.length*100):0};}
  function card(c, size='', used=null, animated=false){
    const rank=c[0]==='T'?'10':c[0],suit=E.SYMBOLS[c[1]];
    return `<span class="card ${c[1]==='h'||c[1]==='d'?'red':''} ${size} ${used===true?'used':used===false?'unused':''} ${animated?'card-enter':''}" role="img" aria-label="${rank} de ${E.SUIT_NAMES[c[1]]}"><span class="rank" aria-hidden="true">${rank}<small>${suit}</small></span><span class="suit" aria-hidden="true">${suit}</span><span class="card-corner" aria-hidden="true">${rank}<small>${suit}</small></span></span>`;
  }
  function cards(list,size='',used=null,animated=false){return `<div class="cards">${list.map(c=>card(c,size,used?used.includes(c):null,animated)).join('')}</div>`;}
  function textCards(list){return list.map(c=>`<span class="${['h','d'].includes(c[1])?'red':''}">${c[0]==='T'?'10':c[0]}${E.SYMBOLS[c[1]]}</span>`).join(' ');}
  function header(){return `<header class="site-header"><div class="header-inner"><button class="brand" data-do="nav" data-view="train" aria-label="Mesa 10, voltar ao treino"><span class="brand-icon" aria-hidden="true">♠</span><span><span class="brand-word">mesa<span>10</span></span><small>O próximo nível é seu</small></span></button><nav class="nav" aria-label="Navegação principal">${[['train','Cash'],['coach','Meu jogo'],['charts','Tabelas'],['guide','Guia'],['history','Progresso']].map(([v,l])=>`<button data-do="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${l}</button>`).join('')}</nav><div class="header-right"><span class="xp-pill"><span aria-hidden="true">✧</span> ${bb(state.profile.xp+state.cash.history.flatMap(h=>h.decisions).reduce((n,d)=>n+(d.correct?(d.assisted?5:20):0),0))} XP</span><button class="icon-btn" data-do="settings" aria-label="Configurações do treino">⚙</button></div></div></header>${storageOK?'':'<div class="save-warning">O navegador não permitiu salvar o progresso. O treino continua funcionando nesta aba.</div>'}`;}
  function pageTop(kicker,title,subtitle,button=true){return `<div class="page-top"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${button?'<button class="outline-btn" data-do="new">↻ &nbsp; Nova sessão</button>':''}</div>`;}
  function footer(){return `<footer class="footer-row"><span><span class="dot"></span>Fichas fictícias · ${storageOK?'Progresso salvo neste navegador':'Sem salvamento disponível'}</span><button data-do="sources">Método e referências ↗</button></footer>`;}
  function sessionCard(){const s=state.session,t=stats(s);return `<section class="session-card" aria-label="Progresso da sessão"><div class="session-heading"><h2>Sua sessão</h2><span>Mão ${s.current+1} de 10</span></div><div class="hand-dots">${s.hands.map((h,i)=>{const done=i<s.current||s.complete,d=h.decisions||[],all=d.length&&d.every(x=>x.correct),any=d.some(x=>x.correct);return `<button class="hand-dot ${i===s.current&&!s.complete?'active':''} ${h.kind==='omaha'?'omaha':''} ${done?(all?'correct':any?'mixed':'wrong'):''}" data-do="review-hand" data-index="${i}" ${done?'':'disabled'} aria-label="Mão ${i+1}${h.kind==='omaha'?', Omaha 4':''}${done?', revisar':''}" ${i===s.current?'aria-current="step"':''}>${done?(all?'✓':any?'·':'×'):i+1}</button>`;}).join('')}</div><div class="session-foot"><span>${t.solo?`${t.accuracy}% de acerto sem ajuda`:'9 Hold’em + 1 Omaha'}</span><span class="gold">10ª mão: Omaha 4 ♣</span></div></section>`;}
  function chipStack(pot){
    const height=Math.min(7,Math.max(2,Math.ceil(Math.log2(pot+1))));
    return `<div class="pot-stacks" aria-hidden="true">${[height-1,height,Math.max(2,height-2)].map((n,i)=>`<span class="chip-tower tower-${i}">${Array.from({length:n},(_,j)=>`<i style="bottom:${j*3}px"></i>`).join('')}</span>`).join('')}</div>`;
  }
  function handRadar(hand){
    if(hand.kind==='omaha')return `<div class="hand-radar omaha-rule"><span class="radar-symbol" aria-hidden="true">♧</span><div><strong>O detalhe está na combinação.</strong><p>Use 2 cartas da mão + 3 da mesa. Sempre.</p></div><span class="rule-token">2 + 3</span></div>`;
    const observations=hand.observations||[],events=[];let cursor=0;
    const observed=e=>events.push({who:hand.villainName||'Adversário',street:e.street,action:e.action,amount:e.amount});
    for(const d of hand.decisions||[]){
      const count=Number.isInteger(d.context?.observationCount)?d.context.observationCount:observations.filter(e=>e.street<d.street||(e.street===d.street&&e.context==='lead')).length;
      while(cursor<Math.min(count,observations.length))observed(observations[cursor++]);
      const amount=d.action==='bet'?d.context?.betSize:d.action==='call'?(d.street===0?1-E.blind(hand.position):d.context?.toCall):d.action==='raise'?E.raiseSize(hand.position):d.action==='shove'?100:0;
      events.push({who:'Você',street:d.street,action:d.action,amount});
    }
    while(cursor<observations.length)observed(observations[cursor++]);
    const labels={check:'deu check',bet:'apostou',call:'pagou',fold:'desistiu',raise:'aumentou',shove:'foi all-in'};
    return `<div class="hand-radar"><div class="radar-heading"><span class="eyebrow">Rastro da mão</span><span>Ações reveladas</span></div>${events.length?`<ol class="action-trail">${events.slice(-5).map(e=>`<li class="${['bet','raise','shove'].includes(e.action)?'attack':''}"><span class="event-dot" aria-hidden="true"></span><span><small>${E.STREETS[e.street]}</small><b>${safe(e.who)}</b> ${labels[e.action]||safe(e.action)}${e.amount?` <em>${bb(e.amount)} BB</em>`:''}</span></li>`).join('')}</ol>`:'<p class="radar-empty"><span aria-hidden="true">◎</span> Sua leitura começa na primeira ação.</p>'}</div>`;
  }
  function table(hand){
    const p=E.initPlay(hand),omaha=hand.kind==='omaha',result=p.result,showResult=omaha?p.phase==='feedback':p.phase==='showdown';
    const board=E.visibleBoard(hand),positions=E.POSITIONS,heroIndex=positions.indexOf(hand.position),post=p.street>0;
    const atmosphere=E.ATMOSPHERES[state.session.atmosphere]||E.ATMOSPHERES.mixed;
    const pressure=!omaha&&p.phase==='decision'&&p.node?.facing?Math.round(p.node.facing/p.node.potBefore*100):0;
    const dealKey=state.session.id+':'+state.session.current+':'+p.street+':'+showResult,animated=dealKey!==lastDealKey;lastDealKey=dealKey;
    let seats='';
    if(!omaha){for(let slot=1;slot<=5;slot++){
      const pos=positions[(heroIndex+slot)%6],isVillain=pos===hand.villainPosition;
      if(showResult&&(slot===3||isVillain))continue;
      const folded=post?!isVillain:positions.indexOf(pos)<heroIndex;
      const stack=isVillain?p.villainStack:100-E.blind(pos);
      seats+=`<div class="seat pos-${slot} ${folded?'folded':''} ${post&&isVillain?'active-player':''} ${post&&isVillain&&pressure?'attacking':''}"><span class="seat-avatar" aria-hidden="true">${post&&isVillain?safe((hand.villainName||'A')[0]):['','♣','♦','♠','♥','♣'][slot]}</span><div class="seat-cards"><span class="card-back"></span><span class="card-back"></span></div><div class="seat-label"><b>${pos}</b><small>${bb(stack)} BB</small></div>${pos==='BTN'?'<span class="dealer" aria-label="Dealer">D</span>':''}<div class="fold-text">${folded?'DESISTIU':post?(isVillain?safe(hand.villainName||'ADVERSÁRIO'):''):' '}</div>${!post&&E.blind(pos)?`<div class="blind-chip"><i aria-hidden="true"></i>${bb(E.blind(pos))}</div>`:''}</div>`;
    }}
    if(omaha||showResult)seats+=`<div class="opponent-reveal"><small>${omaha?'Adversário · 4 cartas':safe(hand.villainName||'Adversário')+' · '+hand.villainPosition}</small>${cards(omaha?hand.villain:hand.villainCards,'mini',showResult?result.villain.holeUsed:null,animated)}</div>`;
    const shownHero=omaha?hand.hero:hand.cards;
    const caption=omaha?'OMAHA 4 · SHOWDOWN':showResult?'SHOWDOWN':post?E.STREETS[p.street].toUpperCase():'AGUARDANDO O FLOP';
    return `<section class="table-panel" id="table-top" aria-label="Mesa de poker"><div class="table-top"><div class="table-caption"><span class="status-dot"></span><strong>${omaha?'Omaha 4':'Cash · 6-max'}</strong><span>${omaha?'Exatamente 2 + 3':'100 BB iniciais'}</span></div><span class="street-badge ${omaha?'gold':''}">${showResult||omaha?'Showdown':E.STREETS[p.street]}</span></div><div class="atmosphere-strip"><button data-do="settings" aria-label="Alterar ritmo de treino"><span aria-hidden="true">${atmosphere.icon}</span>${atmosphere.name}<i aria-hidden="true">⌄</i></button><span class="live-pressure ${pressure>=75?'high':''}"><span class="pressure-bars" aria-hidden="true"><i></i><i></i><i></i></span>${omaha?'Desafio de leitura':pressure?'Aposta de '+pressure+'% do pote':'Observe o ritmo'}</span></div><div class="poker-stage ${omaha?'omaha':''} ${showResult?'revealed':''}"><div class="felt"><div class="felt-pattern"></div><div class="rail-mark mark-left" aria-hidden="true">✦</div><div class="rail-mark mark-right" aria-hidden="true">✦</div><div class="table-watermark"><span aria-hidden="true">♠</span>${omaha?'OMAHA 4':'MESA 10'}<small>ESTUDE CADA DECISÃO</small></div></div>${seats}<div class="board-area"><div class="pot">${chipStack(p.pot)}<div><small>POTE</small><span class="pot-value">${bb(p.pot)} <span class="pot-unit">BB</span></span></div></div>${board.length?cards(board,'mini',null,animated):'<div class="board-ghosts" aria-label="As cinco cartas da mesa ainda não foram reveladas">'+Array.from({length:5},()=>'<span class="ghost-card"><i aria-hidden="true">♠</i></span>').join('')+'</div>'}<div class="board-caption">${caption}</div></div>${showResult?`<div class="result-stamp">${words[result.winner]}</div>`:''}<div class="hero"><div class="hero-topline">${omaha?'Suas quatro cartas':showResult?'Sua mão':p.phase==='decision'?'Sua vez · '+hand.position:'Sua decisão · '+hand.position}</div>${cards(shownHero,'',showResult?result.hero.holeUsed:null,animated)}<div class="hero-label"><span class="hero-indicator" aria-hidden="true"></span><b>VOCÊ${omaha?'':' · '+hand.position}</b><span>${omaha?'2 da mão + 3 da mesa':bb(p.heroStack)+' BB'}</span></div>${hand.position==='BTN'?'<span class="dealer" aria-label="Você está no botão">D</span>':''}</div></div><div class="table-bottom"><div class="street-track">${E.STREETS.map((s,i)=>`<span class="${p.street===i?'current':''} ${p.street>i?'passed':''}">${s}</span>${i<3?'<i></i>':''}`).join('')}</div><button data-do="hint">${p.phase==='decision'?'ⓘ Ver dica':'ⓘ Entender a mão'}</button></div>${handRadar(hand)}</section>`;
  }
  function actionButton(key,label,desc,shortcut,primary=false,risk=false){const icons={fold:'×',call:'=',shove:'↟',raise:'↗',check:'−',bet:'+',hero:'♠',villain:'♣',tie:'='};return `<button class="action ${primary?'primary':''} ${risk?'risk':''}" data-do="play" data-value="${key}"><span class="action-icon" aria-hidden="true">${icons[key]}</span><b>${label}</b><span>${desc}</span><kbd aria-hidden="true">${shortcut}</kbd></button>`;}
  function decision(hand){
    const p=E.initPlay(hand);
    if(p.phase==='showdown')return showdownPanel(hand);
    if(p.phase==='feedback')return feedbackPanel(hand);
    if(hand.kind==='omaha')return `<section class="decision-card" id="decision"><div class="decision-top"><span class="eyebrow">Desafio 10 de 10</span><span class="position-badge">OMAHA 4</span></div><h2>Quem leva o pote?</h2><p>Compare as duas mãos. Use exatamente <strong>2 cartas próprias e 3 da mesa</strong> para cada jogador.</p><div class="actions three">${actionButton('hero','Você vence','Sua mão é maior',1)}${actionButton('villain','Adversário vence','A mão dele é maior',2)}${actionButton('tie','Empate','O pote é dividido',3)}</div><p class="shortcuts">Atalhos: 1, 2 ou 3 para responder</p><div class="model-tag">Cálculo exato das 60 combinações por jogador</div></section>`;
    if(p.street===0){const position=E.POSITION_INFO[hand.position];return `<section class="decision-card" id="decision"><div class="decision-top"><span class="eyebrow">Decisão pré-flop</span><span class="position-badge">${hand.position}</span></div><h2>Qual é a sua jogada?</h2><p>${hand.position==='UTG'?'Você é o primeiro a falar.':`Todos antes de você desistiram.`} A ação está em <strong>${position.name}</strong>.</p><div class="context-stats"><div><small>Para entrar</small><strong>${bb(1-E.blind(hand.position))} BB</strong></div><div><small>Jogadores depois</small><strong>${5-E.POSITIONS.indexOf(hand.position)}</strong></div></div><div class="actions">${actionButton('fold','Desistir','Fold',1)}${actionButton('call','Pagar',hand.position==='SB'?'Completar +0,5 BB':'Limp · 1 BB',2)}${actionButton('shove','All-in','Total de 100 BB',3,false,true)}${actionButton('raise','Aumentar',`Para ${bb(E.raiseSize(hand.position))} BB`,4,true)}</div><p class="shortcuts">Atalhos: 1–4 para decidir · Enter para continuar</p><div class="model-tag">Abertura RFI · tabela didática por posição</div></section>`;}
    const n=E.postflopNode(hand);
    return `<section class="decision-card" id="decision"><div class="decision-top"><span class="eyebrow">Decisão no ${E.STREETS[p.street]}</span><span class="position-badge">${hand.position} × ${hand.villainPosition}</span></div><h2>${n.facing?'Vale pagar essa aposta?':'Como você continua?'}</h2><p>${n.facing?`${n.afterCheck?'Após seu check, o':'O'} adversário apostou <strong>${bb(n.facing)} BB</strong> em um pote de ${bb(n.potBefore)} BB. Neste exercício, escolha entre pagar ou desistir.`:n.inPosition?'O adversário deu check. Você pode passar a vez ou apostar o valor indicado.':'Você fala primeiro nesta rodada. Escolha entre dar check ou apostar o valor indicado.'}</p><div class="context-stats"><div><small>${n.facing?'Para pagar':'Pote atual'}</small><strong>${bb(n.facing||p.pot)} BB</strong></div><div><small>Sua posição</small><strong style="font-size:14px">${n.inPosition?'Em posição':'Fora de posição'}</strong></div></div><div class="actions">${n.facing?actionButton('fold','Desistir','Fold',1)+actionButton('call','Pagar',`${bb(n.facing)} BB`,2):actionButton('check','Dar check','Passar a vez',1)+actionButton('bet','Apostar',`${bb(n.betSize)} BB · ${n.betSize<p.pot*.5-.01?'stack efetivo':'½ pote'}`,2)}</div><p class="shortcuts">Atalhos: 1 ou 2 · Enter para continuar</p><div class="model-tag">Fundamentos pós-flop · adversário simulado</div></section>`;
  }
  function fiveCards(result,label){return `<div class="verdict"><strong>${label} · ${safe(result.name)}</strong>${cards([...result.holeUsed,...result.boardUsed],'small')}<p>${result.holeUsed.length} própria(s) + ${result.boardUsed.length} da mesa<br>${safe(E.describeHand(result))}</p></div>`;}
  function nextLabel(hand){const p=hand.play;return p.pending==='probe'?'Ver reação do adversário':p.pending==='street'?`Ver o ${E.STREETS[p.street+1].toLowerCase()}`:p.pending==='showdown'?'Revelar showdown':state.session.current===9?'Ver resultado da sessão':'Próxima mão';}
  function feedbackPanel(hand){const p=hand.play,fb=p.feedback,last=hand.decisions.at(-1);return `<section class="decision-card feedback-card" id="decision" aria-label="Feedback da decisão"><div class="feedback-mark ${fb.correct?'':'wrong'}">${fb.correct?'✓':'↗'}</div><div class="feedback-label ${fb.correct?'':'wrong'}">${fb.correct?'Boa decisão':'Ajuste de rota'}${last.assisted?' · com ajuda':''}</div><h2>${safe(fb.title)}</h2><p>${safe(fb.explanation)}</p>${hand.kind==='omaha'?fiveCards(fb.result.hero,'Você')+fiveCards(fb.result.villain,'Adversário'):`${p.street>0?`<div class="equity-strip"><div><small>Equidade no modelo</small><strong>${pct(fb.equity)}</strong></div>${fb.odds?`<div><small>Preço para pagar</small><strong>${pct(fb.odds)}</strong></div>`:''}</div>`:''}<div class="feedback-sub">Sua escolha: ${words[last.action]} · ${last.correct?(last.assisted?'+5 XP':'+20 XP'):'0 XP'}</div>`}${p.endReason?`<div class="method-note">${safe(p.endReason)}</div>`:''}<button class="next-button" data-do="advance">${nextLabel(hand)} <span>→</span></button></section>`;}
  function showdownPanel(hand){const result=hand.play.result;return `<section class="decision-card feedback-card" id="decision"><div class="feedback-mark neutral">♠</div><div class="feedback-label">Showdown · cartas abertas</div><h2>${result.winner==='hero'?'O pote é seu.':result.winner==='villain'?'Desta vez, deu adversário.':'Empate. Pote dividido.'}</h2><p>${safe(E.showdownReason(result))}</p>${fiveCards(result.hero,'Você')}${fiveCards(result.villain,'Adversário')}<div class="method-note">O resultado do pote não altera a nota. Uma boa decisão pode perder uma mão.</div><button class="next-button" data-do="advance">${state.session.current===9?'Ver resultado':'Próxima mão'} <span>→</span></button></section>`;}
  function train(){if(state.session.complete)return summary(state.session);const h=current();E.initPlay(h);if(h.kind==='holdem'&&h.play.street>0&&h.play.phase==='decision')E.postflopNode(h);return `${pageTop('Seu treino diário','Cada posição, uma decisão.','10 mãos. Novas posições. Do pré-flop ao river.')}<div class="main-grid">${table(h)}<div class="side-stack">${sessionCard()}${decision(h)}${opponentHUD(h)}<aside class="note-card"><h3><span class="note-icon">✧</span>${h.kind==='omaha'?'A regra que muda tudo':h.play.street?'Pense na decisão, não no resultado':'Observe sua posição'}</h3><p>${h.kind==='omaha'?'No Omaha, uma terceira carta da sua mão nunca entra como kicker. Compare apenas as cinco cartas válidas.':h.play.street?'Pote, preço e faixa do adversário importam. O resultado de uma única mão não mede a qualidade da jogada.':E.POSITION_INFO[h.position].detail}</p></aside></div></div>${footer()}`;}
  function chart(){if(chartContext==='cash')return cashUI.charts();const r=E.rangeStats(chartPosition),open=E.recommended(chartPosition,chartSelected)==='raise';return `${pageTop('Biblioteca de ranges','Sua posição muda o jogo.','Toque em uma combinação para explorar a tabela de abertura.',false)}<div class="chart-layout"><section class="content-panel"><div class="position-tabs" aria-label="Posição da tabela">${E.OPEN_POSITIONS.map(p=>`<button data-do="chart-pos" data-value="${p}" class="${p===chartPosition?'active':''}" aria-pressed="${p===chartPosition}">${p}</button>`).join('')}</div><div class="chart-grid" aria-label="169 classes de mãos de Texas Hold’em">${E.RANKS.map((a,i)=>E.RANKS.map((b,j)=>{const key=i===j?a+b:i<j?a+b+'s':b+a+'o';const yes=E.RANGES[chartPosition].has(key);return `<button class="chart-cell ${yes?'raise':''} ${i===j?'pair':''} ${chartSelected===key?'selected':''}" data-do="chart-hand" data-value="${key}" aria-label="${key}: ${yes?'aumentar':'desistir'}" aria-pressed="${chartSelected===key}">${key}</button>`;}).join('')).join('')}</div><div class="chart-legend"><span><i class="legend-dot green"></i>Aumentar</span><span><i class="legend-dot"></i>Desistir</span><span>s = mesmo naipe · o = naipes diferentes</span></div><p class="chart-description">Pares na diagonal · suited acima · offsuit abaixo. T = 10.</p></section><aside class="content-panel chart-info"><div><div class="eyebrow">${E.POSITION_INFO[chartPosition].short}</div><h2>${chartPosition} · ${E.POSITION_INFO[chartPosition].name}</h2><div class="big-number">${r.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</div><p>${r.combos} das 1.326 combinações possíveis entram nesta faixa de abertura.</p></div><div class="chart-inspect"><span class="eyebrow">Mão selecionada</span><strong>${chartSelected}</strong><div class="answer">${open?'Aumentar para '+bb(E.raiseSize(chartPosition))+' BB':'Desistir'}</div><p>${chartSelected.length===2?'Um par tem 6 combinações de naipes.':chartSelected.endsWith('s')?'Uma mão suited tem 4 combinações de naipes.':'Uma mão offsuit tem 12 combinações de naipes.'}</p><p>Esta é a ação da tabela didática quando ninguém entrou no pote antes de você.</p></div></aside></div><div class="method-note"><strong>Como usar:</strong> cash 6-max, 100 BB, sem ante, primeira abertura. Faixas próprias e simplificadas, orientadas pelos princípios de abertura da Upswing. O small blind usa aumentar/desistir; estratégias com limp também existem. A porcentagem é a cobertura da tabela, não a equidade da mão nem uma frequência GTO. Consultar a tabela durante uma decisão pré-flop marca aquela resposta como assistida.</div>${footer()}`;}
  function sourceLinks(){return `<div class="source-list"><a class="source-link" href="https://upswingpoker.com/6-handed-max-poker-strategy/" target="_blank" rel="noopener noreferrer">Upswing · Estratégia 6-max ↗<small>Posição, abertura e adaptação das faixas.</small></a><a class="source-link" href="https://www.pokerstars.com/pt-BR/poker/games/omaha/" target="_blank" rel="noopener noreferrer">PokerStars · Regras do Omaha ↗<small>Uso obrigatório de 2 cartas próprias + 3 da mesa.</small></a><a class="source-link" href="https://upswingpoker.com/charts/" target="_blank" rel="noopener noreferrer">Upswing · Tabelas de referência ↗<small>Material público para aprofundar o pré-flop.</small></a><a class="source-link" href="https://www.pokerstars.com/poker/games/rules/hand-rankings/" target="_blank" rel="noopener noreferrer">PokerStars · Ranking de mãos ↗<small>Força das combinações e desempates.</small></a></div>`;}
  function guide(){return `${pageTop('Guia · v2.3.1','Sua mesa, em reais simulados.','Nove jogadores · oito Hold’em e uma Omaha por ciclo.',false)}<section class="content-panel"><h2>Entrada, blind e taxa</h2><p>Entrada de R$ 22,00: R$ 20,00 em fichas e R$ 2,00 para a casa. O dealer paga o blind: R$ 0,25 no Hold’em e R$ 1,00 no Omaha. Os demais pagam, aumentam ou desistem. Rake de 5% sobre potes disputados acima de R$ 10,00, excluindo devoluções.</p><p>O gráfico mostra saldo menos todas as entradas. Reentrar acrescenta R$ 20,00 ao custo e às fichas, sem repetir a taxa inicial de R$ 2,00. Tudo é simulado.</p><h2>Fale a língua da mesa</h2><p>Mesa (check): passar sem aposta a completar. Pagar (call): cobrir a aposta. Desistir (fold): sair da disputa. Aumentar (raise): subir a aposta. Tudo (all-in): colocar o saldo disponível. Faixa de mãos (range): combinações possíveis. Taxa da casa (rake): desconto no pote.</p><h2>Princípios de GTO, sem promessa de solver</h2><p>Compare o preço para pagar com o pote final líquido. Pense em faixas, posição, apostas por valor e blefes. Não julgue uma decisão só pelo resultado. As referências desta mesa são aproximações; não são soluções GTO para nove jogadores ou para este blind no botão.</p><p>No Omaha, use exatamente duas cartas da mão e três da mesa. Ao final, todas as cartas são abertas para revisão, inclusive de quem desistiu.</p><p>As primeiras dez mãos geram uma leitura inicial; a calibração é separada por modalidade. Seu progresso fica neste navegador. Login e ranking estão no roadmap.</p><a href="https://blog.gtowizard.com/what-are-pot-odds-in-poker/" target="_blank" rel="noopener">GTO Wizard: preço para pagar</a> · <a href="https://www.pokerstars.com/pt-BR/poker/terms/" target="_blank" rel="noopener">Glossário PokerStars</a><p>Os exercícios independentes da versão anterior, acessíveis nas configurações, continuam em BB e com regras próprias; não movimentam a nova banca em reais.</p></section>${footer()}`;}
  function legacyGuide(){return `${pageTop('Aprenda em português','Entenda o porquê da jogada.','Um guia para consultar antes, durante ou depois do treino.',false)}<div class="guide-grid"><section class="content-panel"><h2>Como funciona o Mesa 10</h2><ol><li><strong>9 mãos de Hold’em:</strong> sua posição muda a cada mão. Você sempre aparece embaixo da mesa.</li><li><strong>Pré-flop:</strong> escolha a primeira ação. Algumas mãos terminam ali; outras continuam.</li><li><strong>Flop, turn e river:</strong> tome novas decisões conforme as cartas aparecem. O contador avança ao terminar a mão.</li><li><strong>10ª mão, Omaha 4:</strong> compare mãos no showdown e confira as cinco cartas usadas.</li></ol><p style="margin-top:16px">Uma decisão correta vale <strong>20 XP</strong>; com dica, <strong>5 XP</strong>. O ganho de fichas não conta pontos. Tabelas e dicas ficam sempre disponíveis.</p></section><section class="content-panel"><div class="eyebrow">Omaha com quatro cartas</div><h2 style="margin-top:10px">Duas da mão. Três da mesa.</h2><div class="rule-big"><div>2<small>cartas próprias</small></div><span>+</span><div>3<small>cartas da mesa</small></div><span>=</span><div>5<small>cartas finais</small></div></div><p>O app testa todas as <strong>60 combinações válidas</strong> de cada jogador. Você não pode jogar só com a mesa, nem usar três cartas próprias.</p><p><strong>E o kicker?</strong> Só vale se estiver dentro da melhor combinação de cinco cartas. Não existe sexta carta para desempatar. No Hold’em, você pode usar 0, 1 ou 2 cartas próprias.</p></section><section class="content-panel guide-wide"><h2>Conheça as posições</h2><div class="position-guide">${E.POSITIONS.map(p=>`<div><h3>${p} · ${E.POSITION_INFO[p].name}</h3><p>${E.POSITION_INFO[p].detail}</p></div>`).join('')}</div><p style="margin-top:18px;font-size:11px">UTG também é chamado de LJ em mesas 6-max. O BB não recebe treino RFI: se todos desistirem, ele já ganhou o pote. No pós-flop, a ordem começa pelo SB e termina no BTN entre os jogadores ativos.</p></section><section class="content-panel"><h2>O vocabulário da mesa</h2><ul><li><strong>BB:</strong> big blind, a unidade usada para medir as fichas.</li><li><strong>Fold:</strong> desistir da mão. <strong>Check:</strong> passar a vez sem aposta a pagar.</li><li><strong>Call:</strong> pagar uma aposta. <strong>Limp:</strong> pagar o blind sem aumentar.</li><li><strong>Raise:</strong> aumentar uma aposta. <strong>All-in:</strong> colocar todas as fichas.</li><li><strong>RFI:</strong> primeira abertura do pote, sem jogadores que entraram antes.</li><li><strong>Flop:</strong> as primeiras 3 cartas. <strong>Turn:</strong> a 4ª. <strong>River:</strong> a 5ª.</li><li><strong>Range:</strong> faixa de mãos possíveis. <strong>Suited:</strong> mesmo naipe.</li></ul></section><section class="content-panel"><h2>Preço, pote e equidade</h2><p>Se o pote tem <strong>10 BB</strong> e o adversário aposta <strong>5 BB</strong>, você paga 5 para disputar um pote final de 20. O preço é <strong>5 ÷ 20 = 25%</strong>.</p><p>A equidade é sua parcela média do pote contra uma faixa, incluindo os empates. No flop e no turn, o app estima esse valor com <strong>400 simulações</strong>. No river, compara todas as combinações legais da faixa ilustrativa.</p><p>O modelo aceita pagar ou desistir quando a estimativa está a até <strong>6 pontos percentuais</strong> do preço. Fora do river, apostas futuras e realização de equidade podem mudar a decisão real.</p></section><section class="content-panel guide-wide"><h2>Ranking: da mão mais forte à mais fraca</h2><ol class="ranking"><li>Royal flush</li><li>Straight flush</li><li>Quadra</li><li>Full house</li><li>Flush</li><li>Sequência</li><li>Trinca</li><li>Dois pares</li><li>Um par</li><li>Carta alta</li></ol><p style="margin-top:17px;font-size:12px">O ás pode ser baixo em A–2–3–4–5 ou alto em 10–J–Q–K–A. Naipes não têm hierarquia para desempatar.</p></section><section class="content-panel guide-wide"><h2>O que está por trás do treino</h2><p><strong>Pré-flop:</strong> faixas didáticas próprias, inspiradas em princípios públicos de estratégia 6-max. Aberturas de 2,5 BB, ou 3 BB no SB, são convenções deste treino. Não há rake ou ante.</p><p><strong>Pós-flop:</strong> o adversário usa uma faixa fixa ilustrativa. Léo, Nina e Rafa têm probabilidades diferentes de apostar, pagar e desistir, sorteadas uma vez neste navegador. O Coach mede somente ações já observadas; não lê os perfis internos. Não há reaumentos; ele pode apostar, pagar, dar check ou desistir. Depois do seu check fora de posição, ele pode apostar e devolver a decisão a você. Nas configurações, escolha Mesa mista, Pressão alta ou Imprevisível. As apostas variam de 25% a 125% do pote, limitadas pelas fichas disponíveis. O roteiro é sorteado uma vez por mão e independe da força das cartas. O modelo ensina fundamentos, não explora um adversário profissional nem calcula uma solução GTO.</p><p><strong>Amostragem:</strong> no modo equilibrado, 4 ou 5 das 9 mãos de Hold’em estão dentro da faixa de abertura. No modo baralho real, as duas cartas são sorteadas sem esse filtro; as posições continuam variando e cenários repetidos de posição + classe são evitados. O adversário é sorteado dentro da faixa ilustrativa nos dois modos. Omaha usa um baralho completo embaralhado, sem filtro.</p><p><strong>Privacidade:</strong> o progresso fica neste navegador. Quando você solicita uma análise com Gemini, apenas o contexto visível da mão simulada e as contagens do adversário são enviados à API. Cartas ocultas, cartas futuras e o histórico completo não são enviados. A API gratuita do Google pode usar o conteúdo para melhorar seus produtos. Trocar de dispositivo ou endereço não transfere o histórico.</p>${sourceLinks()}<div class="source-date">Referências consultadas em 31/10/2026 · App independente, sem vínculo com as fontes.</div></section></div>${footer()}`;}
  function statBox(value,label){return `<div class="stat-box"><strong>${value}</strong><small>${label}</small></div>`;}
  function history(){const p=state.profile;return `${pageTop('Seu caminho até aqui','Pequenas decisões. Evolução real.','Acompanhe sua precisão e reveja as mãos que já treinou.',false)}<div class="stat-grid">${statBox(p.sessions,'Sessões concluídas')}${statBox(p.unassisted?pct(p.unassistedCorrect/p.unassisted):'—','Precisão sem ajuda')}${statBox(p.bestStreak,'Melhor sequência de acertos')}${statBox(bb(p.xp),'XP acumulado')}</div>${state.history.length?`<div class="history-list">${[...state.history].reverse().map(s=>{const t=stats(s);return `<article class="history-row"><div><strong>${new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(new Date(s.completedAt))}</strong><small>10 mãos · ${t.total} decisões · ${t.solo?t.accuracy+'% sem ajuda':'Todas com ajuda'} · ${t.assisted} assistida(s)</small></div><button class="outline-btn" data-do="review-session" data-id="${safe(s.id)}">Revisar →</button></article>`;}).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">♧</div><h2>Sua história começa na mesa.</h2><p>Conclua uma sessão de 10 mãos para ver seu histórico aqui.</p><button class="next-button" data-do="nav" data-view="train">Continuar treino <span>→</span></button></div>`}${footer()}`;}
  function reviewHand(hand,index){const d=hand.decisions||[];return `<details class="review-item"><summary><span class="review-index">${String(index+1).padStart(2,'0')}</span><span class="review-cards">${textCards(hand.kind==='omaha'?hand.hero:hand.cards)}</span><span class="review-meta">${hand.kind==='omaha'?'Omaha 4':hand.position}<small>${d.length} decisão(ões)${d.some(x=>x.assisted)?' · com ajuda':''}</small></span><span class="review-score ${d.some(x=>!x.correct)?'wrong':''}">${d.filter(x=>x.correct).length}/${d.length} ✓</span></summary><div class="review-body">${d.map(x=>`<div class="review-decision"><strong>${hand.kind==='omaha'?'Showdown':E.STREETS[x.street]} · ${words[x.action]} ${x.correct?'✓':'↗'}${x.assisted?' · assistida':''}</strong><p>${safe(x.explanation)}</p></div>`).join('')}${hand.play?.result?`<div class="review-decision"><strong>Cartas usadas no showdown</strong>${fiveCards(hand.play.result.hero,'Você')}${fiveCards(hand.play.result.villain,'Adversário')}</div>`:''}</div></details>`;}
  function summary(session){const t=stats(session);return `<section class="summary"><div class="summary-hero"><div class="trophy">✧</div><div class="eyebrow">10 mãos · sessão concluída</div><h1>${t.accuracy>=80?'Boa leitura de jogo.':t.accuracy>=50?'Cada mão ensina alguma coisa.':'Seu próximo acerto começa aqui.'}</h1><p>Reveja suas decisões e leve o aprendizado para a próxima sessão.</p><button class="next-button" data-do="new">Treinar mais 10 mãos <span>→</span></button></div><div class="stat-grid">${statBox(t.solo?t.accuracy+'%':'—','Precisão sem ajuda')}${statBox(t.total,'Decisões tomadas')}${statBox(t.correct,'Respostas aceitas')}${statBox(t.assisted,'Decisões com ajuda')}</div><p class="summary-detail">9 Hold’em + 1 Omaha 4 · ${session.mode==='deck'?'Cartas sem filtro de faixa':'Sorteio equilibrado para estudo'}</p>${evReviewCard(session)}<div class="review-list">${session.hands.map(reviewHand).join('')}</div></section>${footer()}`;}

  function opponentHUD(h){
    if(h.kind!=='holdem')return '';
    const r=C.profile(C.readOpponent(state,h.villainId)),has=r.opportunities>0;
    return `<aside class="opponent-hud"><div class="hud-heading"><span class="avatar">${safe((h.villainName||'?')[0])}</span><div><span class="eyebrow">Leitura do adversário</span><h3>${safe(h.villainName||'Nova leitura')} <span class="bot-label">simulado</span></h3></div><span class="radar-pulse" aria-hidden="true">◎</span></div><div class="hud-meter-label"><span>Aposta ao ter a vez</span><strong>${has?pct(r.aggression):'—'}</strong></div><div class="aggression-segments" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i class="${has&&i<Math.round(r.aggression*12)?'lit':''}"></i>`).join('')}</div><p>${r.label} · ${r.opportunities} oportunidade${r.opportunities===1?'':'s'}</p><button class="text-button" data-do="nav" data-view="coach">Estudar leitura no Coach <span>↗</span></button></aside>`;
  }
  function activeCoach(){
    const snapshot=C.snapshot(state);if(!snapshot)return null;
    const key=JSON.stringify(snapshot);
    if(!localAnalyses.has(key)){
      const h=current(),equity=h.play.phase==='feedback'?h.decisions.at(-1)?.context?.equity:h.play.node?.equity?.value;
      localAnalyses.set(key,C.analyze(snapshot,equity??undefined));
      if(localAnalyses.size>100)localAnalyses.delete(localAnalyses.keys().next().value);
    }
    return {snapshot,analysis:localAnalyses.get(key),key};
  }
  function opponentCard(o){
    const r=C.profile(C.readOpponent(state,o.id)),metric=(v,n)=>v===null?'—':`${pct(v)} <small>em ${n}</small>`;
    return `<article class="opponent-card ${o.id===current().villainId&&!state.session.complete?'current-opponent':''}"><div class="opponent-heading"><span class="avatar">${safe(o.name[0])}</span><div><h3>${safe(o.name)}</h3><p>${r.hands} mão(s) com ação observada</p></div><span class="bot-label">bot</span></div><div class="read-label">${r.label}</div><div class="metric-row"><span>Aposta ao ter a vez</span><strong>${metric(r.aggression,r.opportunities)}</strong></div><div class="meter"><span style="width:${(r.aggression||0)*100}%"></span></div><div class="metric-row"><span>Desiste para aposta</span><strong>${metric(r.foldRate,r.faced)}</strong></div><div class="meter gold"><span style="width:${(r.foldRate||0)*100}%"></span></div><p class="sample-note">${r.confidence} · ${r.bets} apostas / ${r.checks} checks · ${r.folds} folds / ${r.calls} calls</p></article>`;
  }
  function evReviewCard(session){
    const r=C.evReview(session);
    return `<section class="ev-review"><div><span class="eyebrow">Revisão de decisões de pagar ou desistir</span><h3>${r.opportunities?bb(r.missed)+' BB de diferença no modelo':'EV em observação'}</h3><p>${r.opportunities} decisão(ões) comparada(s). Soma da diferença para a melhor opção de EV no modelo sem apostas futuras. Não é prejuízo real nem lucro recuperável garantido; não inclui pré-flop ou apostas por valor.</p></div><button class="outline-btn" data-do="nav" data-view="coach">Explorar o Coach →</button></section>`;
  }
  function aiCard(spot){
    const note=spot&&aiNotes.get(spot.key);
    let status=aiConnection.status==='ready'?'Chave configurada':aiConnection.status==='checking'?'Verificando conexão…':aiConnection.status==='idle'?'Conexão opcional':'IA não conectada neste endereço';
    const labels={summary:'Sua decisão',opponentRead:'Leitura do adversário',adjustment:'Ajuste para estudar',exercise:'Próximo exercício',caveat:'Limite da análise'};
    return `<section class="content-panel ai-card"><div class="coach-section-top"><div><span class="eyebrow">Análise com IA</span><h2>Uma segunda leitura.</h2></div><span class="mode-pill">${status}</span></div><p>O coach local continua disponível. A IA explica a mão e sugere hipóteses para testar, sem alterar a pontuação.</p>${note?.analysis?`<div class="ai-response">${Object.entries(labels).map(([k,l])=>`<div><h3>${l}</h3><p>${safe(note.analysis[k])}</p></div>`).join('')}<small>Gerado por ${safe(note.model)} · confira com o cálculo local</small></div>`:note?.error?`<div class="method-note" role="status">${safe(note.error)}</div>`:''}<div class="coach-actions">${aiConnection.status==='ready'?`<button class="next-button" data-do="ask-ai" ${!spot||aiBusy||note?.analysis?'disabled':''}>${aiBusy?'Analisando…':note?.analysis?'Análise recebida':'Analisar esta mão com Gemini'} <span>✧</span></button>`:`<button class="outline-btn" data-do="coach-connect" ${aiConnection.status==='checking'?'disabled':''}>Verificar conexão</button>`}<button class="text-button" data-do="coach-setup">Sobre a revisão com IA</button></div><p class="privacy-note">Ao solicitar, você envia suas cartas, a mesa revelada e contagens de ações desta simulação ao Google. Nenhuma carta oculta ou futura é enviada. No plano gratuito, o conteúdo pode ser usado para melhorar os produtos do Google.</p></section>`;
  }
  function evLab(spot){
    if(!spot||!spot.snapshot.street)return `<section class="content-panel ev-lab"><span class="eyebrow">Laboratório de EV</span><h2>Quanto vale a decisão?</h2><p>Avance até o flop para comparar preço, equidade e valor esperado. EV mede o resultado médio de uma hipótese repetida muitas vezes.</p></section>`;
    const {snapshot:s,analysis:a}=spot,facing=s.toCall>0;
    const fold=a.read.faced>=10?Math.round(a.read.foldRate*100):30;
    return `<section class="content-panel ev-lab" data-pot="${s.pot}" data-call="${s.toCall}" data-bet="${s.betSize}"><span class="eyebrow">Laboratório de EV · hipótese editável</span><h2>Teste antes de concluir.</h2><p>${facing?`Pote de ${bb(s.pot)} BB já inclui a aposta adversária. Pagar custa ${bb(s.toCall)} BB.`:`Pote de ${bb(s.pot)} BB. Sua aposta: ${bb(s.betSize)} BB.`}</p><label class="range-label" for="ev-equity">${facing?'Sua equidade':'Equidade quando receber call'} <output id="ev-equity-label">${Math.round(a.equity*100)}%</output></label><input id="ev-equity" type="range" min="0" max="100" value="${Math.round(a.equity*100)}">${!facing?`<label class="range-label" for="ev-fold">Hipótese de desistência <output id="ev-fold-label">${fold}%</output></label><input id="ev-fold" type="range" min="0" max="100" value="${fold}"><p class="sample-note">${a.read.faced>=10?'Valor inicial: frequência observada, que pode mudar neste cenário.':'30% é um cenário ilustrativo, não uma previsão do adversário.'} A equidade inicial usa uma faixa fixa; ajuste-a para representar quem pagaria sua aposta.</p>`:''}<div id="ev-result" class="ev-result" aria-live="polite"></div><p class="privacy-note">Sem apostas futuras, raises ou rake. No flop e turn, o valor é apenas uma aproximação. Os controles não alteram a nota do treino nem estimam renda real.</p></section>`;
  }
  function coachPage(){
    const spot=activeCoach();
    return `${pageTop('Observe. Compare. Aprenda.','Leia o adversário. Treine sua vantagem.','Um coach em português para transformar ações observadas em hipóteses de jogo.',false)}<div class="coach-intro"><span class="mode-pill">Leitura local ativa</span><span>3 adversários simulados · histórico neste navegador</span></div><div class="opponents-grid">${state.opponents.map(opponentCard).join('')}</div><div class="coach-layout"><div class="coach-main"><section class="content-panel local-coach"><div class="coach-section-top"><div><span class="eyebrow">${spot?`Mão ${state.session.current+1} · ${E.STREETS[spot.snapshot.street]} · ${spot.snapshot.position}`:'Continue seu treino'}</span><h2>${spot?'Uma decisão, com contexto.':'A próxima leitura começa na mesa.'}</h2></div><span class="mode-pill">Cálculo local</span></div>${spot?`<div class="coach-hand">${cards(spot.snapshot.cards,'small')}<span>${spot.snapshot.board.length?textCards(spot.snapshot.board):'Mesa ainda não revelada'}</span></div><div class="coach-suggestion"><small>Referência do modelo${spot.snapshot.phase==='feedback'?' · revisão da decisão':''}</small><strong>${spot.analysis.label}</strong></div><p>${safe(spot.analysis.reason)}</p><div class="coach-insight"><h3>${spot.analysis.read.label}</h3><p>${safe(spot.analysis.read.tip)}</p></div><p class="privacy-note">${safe(spot.analysis.limits)} ${spot.snapshot.phase==='decision'?'Consultar o Coach marca esta decisão como assistida.':''}</p>`:'<p>O Coach analisa as decisões de Hold’em. No Omaha, use a comparação exata de duas cartas próprias e três da mesa. Comece outra mão para continuar a leitura.</p>'}<button class="outline-btn" data-do="nav" data-view="train">← Voltar à mesa</button></section>${aiCard(spot)}</div><aside>${evLab(spot)}<section class="content-panel reading-guide"><h3>O que está sendo medido?</h3><p><strong>Aposta ao ter a vez:</strong> apostas ÷ (apostas + checks), quando o adversário fala primeiro ou reage ao seu check. Checks impostos em sessões antigas não entram. Mudar o clima da mesa pode mudar as frequências; o histórico agrega esses cenários.</p><p><strong>Desiste para aposta:</strong> folds ÷ (folds + calls), ao enfrentar suas apostas pós-flop.</p><p>Esses números não são VPIP, PFR ou o fator de agressividade tradicional. As posições variam; a amostra de um cenário pode não representar outro.</p><p>Uma tendência aparece a partir de 12 oportunidades, ainda sem certeza estatística. Os dados cobrem a sessão atual e até 50 sessões concluídas.</p></section></aside></div>${evReviewCard(state.session)}${footer()}`;
  }
  function updateEV(){
    const lab=document.querySelector('.ev-lab[data-pot]');if(!lab)return;
    const e=Number(document.getElementById('ev-equity').value)/100;
    const pot=Number(lab.dataset.pot),call=Number(lab.dataset.call),bet=Number(lab.dataset.bet);
    const fold=Number(document.getElementById('ev-fold')?.value||0)/100;
    document.getElementById('ev-equity-label').textContent=pct(e);
    const foldLabel=document.getElementById('ev-fold-label');if(foldLabel)foldLabel.textContent=pct(fold);
    const ev=call?C.callEV(e,pot,call):C.betEV(e,pot,bet,fold);
    document.getElementById('ev-result').innerHTML=`<small>EV de ${call?'pagar':'apostar'} neste cenário</small><strong class="${ev<0?'red':''}">${ev>0?'+':''}${bb(ev)} BB</strong><p>${call?`Desistir vale 0 BB a partir desta decisão. Preço mínimo: ${pct(call/(pot+call))}.`:`Um blefe sem equidade precisa de ${pct(bet/(pot+bet))} de desistências para empatar.`}</p><code>${call?'EV = equidade × (pote + call) − call':'EV = fold × pote + (1 − fold) × [equidade × (pote + 2 × aposta) − aposta]'}</code>`;
  }
  function coachSetup(){openModal('Revisão com IA',`<p>A revisão com Gemini é opcional e precisa de conexão. Se estiver indisponível neste endereço, continue pelo diagnóstico local: seu treino e progresso são preservados.</p>`);}

  async function checkAI(){
    if(aiConnection.status==='checking')return;
    aiConnection={status:'checking'};render();
    const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);
    try{const r=await fetch('/api/coach',{signal:ctrl.signal,cache:'no-store'});if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw new Error();const j=await r.json();aiConnection={status:j.ready?'ready':'offline',model:j.model};}
    catch(_){aiConnection={status:'offline'};}
    finally{clearTimeout(timer);if(view==='coach')render();}
  }
  async function askAI(){
    const spot=activeCoach();if(!spot||aiBusy||aiConnection.status!=='ready'||aiNotes.get(spot.key)?.analysis)return;
    markAssisted();aiBusy=true;aiNotes.delete(spot.key);render();
    const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),22000);
    const errors={quota_exceeded:'A cota da API foi atingida. O coach local continua funcionando. Tente novamente mais tarde.',not_configured:'A chave ainda não foi configurada no servidor.',timeout:'A IA demorou para responder. Continue com a análise local.',provider_unavailable:'O provedor está indisponível ou a chave precisa ser verificada. A análise local permanece disponível.'};
    try{const r=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(spot.snapshot),signal:ctrl.signal});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(r.status===429?'quota_exceeded':j.code||'provider_unavailable');if(!j.analysis)throw new Error('provider_unavailable');aiNotes.set(spot.key,{analysis:j.analysis,model:j.model});}
    catch(error){aiNotes.set(spot.key,{error:errors[error.name==='AbortError'?'timeout':error.message]||'Não foi possível analisar agora. O coach local continua disponível.'});}
    finally{clearTimeout(timer);aiBusy=false;if(aiNotes.size>30)aiNotes.delete(aiNotes.keys().next().value);if(view==='coach')render();announce('Consulta à IA concluída.');}
  }
  document.addEventListener('input',event=>{if(['ev-equity','ev-fold'].includes(event.target.id))updateEV();});

  function render(){app.innerHTML=header()+`<main class="main main-${view}" id="main">${view==='train'?cashUI.table():view==='classic'?train():view==='charts'?chart():view==='guide'?cashGuide():view==='coach'?cashUI.report():view==='history'?cashUI.history():view==='review'?summary(reviewedSession):history()}</main>`;save();cashUI.schedule(view);}
  function cashGuide(){return `<div class="page-top"><div><div class="eyebrow">Guia do cash lab</div><h1>Entenda o jogo e a leitura.</h1><p>O treino avalia decisões. O resultado das fichas é outra medida.</p></div></div><div class="guide-grid"><section class="content-panel"><h2>Dez mãos para começar</h2><p>Jogue nove mãos de Hold’em e uma de Omaha. Depois da décima, o painel Meu jogo mostra prioridades ligadas às suas decisões sem ajuda. Dez mãos são uma amostra inicial; a análise evolui continuamente.</p><p>As cartas são sorteadas sem escolher vencedores ou garantir mãos fortes. A posição inicial é aleatória; depois o botão gira no sentido horário. Seu assento permanece embaixo.</p></section><section class="content-panel"><h2>A regra do dealer</h2><p>Nesta mesa, o dealer coloca 1 ficha como aposta inicial. Os outros jogadores precisam pagar 1 ficha, aumentar ou desistir antes do flop. Se alguém aumentar, cada jogador precisa completar o valor vigente ou estar all-in. A entrada do dealer já conta: ele paga somente a diferença de um aumento.</p><p>Não há small blind nem big blind neste formato. A ação começa à esquerda do dealer: UTG, UTG+1, MP, HJ, CO e BTN. O botão gira a cada mão. As tabelas são aproximações didáticas por ordem de ação, sem solução de solver para esta regra.</p></section><section class="content-panel"><h2>Sua banca simulada</h2><p>Você começa com 1.000 fichas: 100 fichas na mesa e 900 fichas na reserva. Apostas saem do stack; o vencedor recebe o pote. Reentradas usam a reserva e não apagam o resultado acumulado. Não existe multa por errar uma resposta.</p><p>All-ins respeitam o saldo. Jogadores concorrem apenas aos potes para os quais são elegíveis; excessos não pagos são devolvidos. Os bots repõem fichas entre mãos quando ficam abaixo de 1 ficha.</p></section><section class="content-panel"><h2>Hold’em e Omaha</h2><p>No Hold’em, o aumento é no-limit e a melhor mão pode usar 0, 1 ou 2 cartas próprias. No Omaha 4, as apostas respeitam o limite do pote e o showdown usa exatamente 2 cartas próprias e 3 comunitárias.</p><p>O app separa as estatísticas das modalidades. Empates dividem o pote; centésimos restantes vão ao primeiro vencedor à esquerda do botão.</p></section><section class="content-panel guide-wide"><h2>Como interpretar o diagnóstico</h2><p>O pré-flop usa faixas de abertura próprias e heurísticas simplificadas de defesa. O pós-flop estima equidade contra mãos aleatórias, com 200 amostras no Hold’em e 120 no Omaha, somente com cartas visíveis. Não estima ranges condicionados a apostas, realização futura ou rake. Desvios desse modelo são pontos para estudar, não prova de erro GTO.</p><p>Os bots usam as próprias cartas, o board e probabilidades de estilo. Não leem suas cartas ocultas. O Coach usa apenas as suas decisões e ações públicas; as tendências exibem a quantidade de observações.</p><p>Uma jogada boa pode perder e uma jogada ruim pode ganhar. A banca simulada ajuda a observar variação e disciplina; não prevê rendimento real. Priorize a qualidade do processo.</p></section><section class="content-panel"><h2>Treino direcionado</h2><p>Em Meu jogo, abra Praticar minhas decisões. Você refaz os cenários em que se afastou da referência, sem movimentar a banca e sem contaminar a calibração com respostas ensaiadas. A próxima meta acompanha cada ponto.</p><p>Consultar referência ou tabelas enquanto decide marca a decisão como assistida. Na mesa, escolha animação lenta, normal, rápida ou sem animação.</p></section><section class="content-panel"><h2>Seu treino, no celular</h2><p>Adicione o Mesa 10 à tela inicial do iPhone ou Android. Nas configurações, consulte as instruções de instalação e o status do treino offline.</p><p>Abra o app uma vez com internet e espere a indicação de que o modo offline está pronto. Mesa, tabelas e diagnóstico local continuam disponíveis sem conexão. Só a revisão com Gemini precisa de internet.</p><p>As cartas de todos aparecem ao encerrar a mão, inclusive de quem desistiu. Isso é um recurso de estudo: a revelação não muda o resultado nem a avaliação das suas decisões.</p><p>Seu progresso é salvo neste navegador e dispositivo. A consulta ao Gemini envia apenas um resumo da simulação quando você solicita.</p><button data-do="pwa-help" class="outline-btn">Instalar no celular ↗</button></section></div><div class="method-note">Os exercícios independentes da versão anterior continuam disponíveis. Eles têm stacks reiniciados e pontuação própria.</div><button data-do="cash-classic" class="outline-btn">Abrir exercícios anteriores</button>${footer()}`;}

  function announce(text){document.getElementById('announcer').textContent=text;}
  function scrollToArea(id){if(window.innerWidth<=850)requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}
  function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=text;el.setAttribute('role','status');document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4000);}
  function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-do="close-modal" aria-label="Fechar">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
  function newSession(force=false){if(!force&&!state.session.complete&&state.session.hands.some(h=>h.decisions?.length)){openModal('Começar uma nova sessão?',`<p>A sessão atual está na mão ${state.session.current+1} de 10. Seu XP acumulado permanece, mas esta sessão incompleta não entrará no histórico.</p><div class="modal-actions"><button class="outline-btn" data-do="close-modal">Continuar esta sessão</button><button class="next-button" data-do="new-force">Começar outra</button></div>`);return;}state.session=E.createSession({...state.prefs,opponents:state.opponents});view='classic';modal.close();render();window.scrollTo({top:0,behavior:'instant'});announce('Nova sessão. Mão 1 de 10.');}
  function recordDecision(d){if(!d)return;const p=state.profile;p.answered++;if(d.correct){p.correct++;p.xp+=d.assisted?5:20;}if(!d.assisted){p.unassisted++;if(d.correct){p.unassistedCorrect++;p.streak++;p.bestStreak=Math.max(p.bestStreak,p.streak);}else p.streak=0;}else p.streak=0;}
  function play(action){if(view!=='classic'||state.session.complete)return;const hand=current();const result=E.act(hand,action);if(!result)return;recordDecision(result);render();announce(`${result.correct?'Resposta aceita.':'Vamos ajustar.'} ${hand.play.feedback.title}`);scrollToArea('decision');}
  function advance(){const hand=current();const outcome=E.advance(hand);if(outcome==='done'){
    if(state.session.current===9){state.session.complete=true;state.session.completedAt=new Date().toISOString();state.profile.sessions++;state.history.push(JSON.parse(JSON.stringify(state.session)));state.history=state.history.slice(-50);}
    else state.session.current++;
  }render();announce(state.session.complete?'Sessão concluída.':`Mão ${state.session.current+1}. ${E.STREETS[current().play?.street||0]}.`);scrollToArea(state.session.complete?'main':'table-top');}
  function markAssisted(){const h=current();if(!state.session.complete&&h.play?.phase==='decision'){h.play.assisted=true;save();}}
  function hint(){const h=current(),p=E.initPlay(h);if(p.phase==='decision')markAssisted();
    if(h.kind==='omaha')openModal('Omaha: comece pela regra',`<p>Escolha <strong>exatamente duas</strong> das suas quatro cartas e <strong>três</strong> das cinco cartas da mesa. Repita para o adversário e compare as melhores combinações.</p><p>Para fazer flush, você precisa de duas cartas daquele naipe na mão e três na mesa. Um ás isolado do naipe não basta.</p><p>O kicker só participa se fizer parte dessas cinco cartas. Se as melhores cinco tiverem os mesmos valores, é empate.</p><p class="modal-note">${p.phase==='decision'?'Esta decisão foi marcada como assistida.':''}</p>`);
    else if(p.street===0){const action=E.recommended(h.position,h.cards);openModal(`${E.handClass(h.cards)} no ${h.position}`,`<p><strong>${action==='raise'?'Aumentar para '+bb(E.raiseSize(h.position))+' BB':'Desistir'}</strong> é a ação da tabela didática nesta situação.</p><p>${safe(E.feedback(h,action).explanation)}</p><p>${safe(E.POSITION_INFO[h.position].detail)}</p><p class="modal-note">${p.phase==='decision'?'Esta decisão foi marcada como assistida.':''}</p><button class="next-button" data-do="open-current-chart">Ver a tabela desta posição <span>→</span></button>`);}
    else{const n=p.node||E.postflopNode(h);openModal('Leia o preço da decisão',`<p>Sua equidade ${n.equity.exact?'calculada':'aproximada'} é <strong>${pct(n.equity.value)}</strong> contra a faixa ilustrativa do adversário.</p><p>${n.facing?`Você precisa pagar ${bb(n.facing)} BB. O preço exige aproximadamente <strong>${pct(n.odds)}</strong> de equidade.`:'Sem aposta a pagar, você pode controlar o pote com check ou apostar por valor.'}</p><p>O modelo sugere <strong>${words[n.expected].toLowerCase()}</strong>${n.accepted.length>1?', mas também aceita a outra opção neste caso marginal':''}.</p><p class="modal-note">${p.phase==='decision'?'Esta decisão foi marcada como assistida. ':''}Este modelo não é uma solução GTO.</p>`);}
  }
  function settings(){
    openModal('Seu ritmo de treino',`<p class="settings-intro">Escolha a pressão da mesa e como receber suas cartas.</p><h3 class="setting-section-title">01 <span>Clima da mesa</span></h3><div class="atmosphere-options">${Object.entries(E.ATMOSPHERES).map(([key,m])=>`<label class="setting-option atmosphere-option"><input type="radio" name="atmosphere" value="${key}" ${state.prefs.atmosphere===key?'checked':''}><span class="setting-symbol" aria-hidden="true">${m.icon}</span><span><strong>${m.name}</strong><small>${m.description}</small></span></label>`).join('')}</div><h3 class="setting-section-title">02 <span>Distribuição de cartas</span></h3><label class="setting-option"><input type="radio" name="mode" value="balanced" ${state.prefs.mode==='balanced'?'checked':''}><span><strong>Equilibrado para estudo</strong><small>4 ou 5 mãos dentro da faixa e as demais fora. Mais decisões em cada sessão.</small></span></label><label class="setting-option"><input type="radio" name="mode" value="deck" ${state.prefs.mode==='deck'?'checked':''}><span><strong>Baralho real</strong><small>Cartas sem filtro. É normal receber mais mãos para desistir. O adversário usa a faixa ilustrativa.</small></span></label><p class="modal-note">Vale para a próxima sessão. As posições variam; a 10ª mão continua sendo Omaha 4. Os ritmos alteram probabilidades dos bots, não as tabelas ou sua nota.</p><button class="next-button" data-do="save-settings">Salvar preferências <span>✓</span></button>`);
  }
  function settings(){if(view==='classic')classicSettings();else cashUI.settings();}
  function sources(){openModal('Método e referências',`<p>O Mesa 10 usa faixas próprias de abertura para treino 6-max com 100 BB. As fontes orientam os fundamentos; as tabelas foram simplificadas e <strong>não são saídas de solver</strong>.</p><p>No cash contínuo, a equidade pós-flop usa mãos aleatórias e as notas são heurísticas, sem ajuste de ranges ao ante ou às apostas. Os exercícios independentes preservam a faixa fixa da versão anterior. Os limites estão no Guia. O showdown calcula as melhores cinco cartas pelas regras de cada modalidade.</p>${sourceLinks()}<p class="source-date">Consultadas em 31/10/2026. Sem afiliação às fontes.</p>`);}
  function navigate(to){if(to==='charts')chartContext=view==='classic'?'classic':'cash';if(['charts','coach'].includes(to)&&state.cash.hand?.phase==='betting'&&state.cash.hand?.actor===0){state.cash.hand.assisted=true;save();}if(to==='coach'&&view==='classic')markAssisted();if(to==='charts'&&view==='classic'&&!state.session.complete){const h=current();E.initPlay(h);if(h.kind==='holdem'&&h.play.street===0&&h.play.phase==='decision'){markAssisted();chartPosition=h.position;chartSelected=E.handClass(h.cards);}}view=to;modal.close();render();window.scrollTo({top:0,behavior:'instant'});}
  document.addEventListener('click',event=>{
    const button=event.target.closest('[data-do]');if(!button||button.disabled)return;
    const action=button.dataset.do;
    if(window.MesaPWA?.handle(action,{save,openModal,toast}))return;
    if(cashUI.handle(action,button))return;
    if(action==='nav')navigate(button.dataset.view);
    else if(action==='play')play(button.dataset.value);
    else if(action==='advance')advance();
    else if(action==='new')newSession();
    else if(action==='new-force')newSession(true);
    else if(action==='settings')settings();
    else if(action==='save-settings'){state.prefs.mode=modal.querySelector('input[name="mode"]:checked').value;state.prefs.atmosphere=modal.querySelector('input[name="atmosphere"]:checked').value;save();modal.close();toast('Preferência salva para a próxima sessão.');}
    else if(action==='close-modal')modal.close();
    else if(action==='hint')hint();
    else if(action==='sources')sources();
    else if(action==='coach-connect')checkAI();
    else if(action==='coach-setup')coachSetup();
    else if(action==='ask-ai')askAI();
    else if(action==='chart-pos'){chartPosition=button.dataset.value;render();}
    else if(action==='chart-hand'){chartSelected=button.dataset.value;render();}
    else if(action==='open-current-chart'){chartPosition=current().position;chartSelected=E.handClass(current().cards);navigate('charts');}
    else if(action==='review-session'){reviewedSession=state.history.find(s=>s.id===button.dataset.id);view='review';render();window.scrollTo({top:0,behavior:'instant'});}
    else if(action==='review-hand'){const i=Number(button.dataset.index);openModal(`Revisar mão ${i+1}`,reviewHand(state.session.hands[i],i));modal.querySelector('details').open=true;}
  });
  document.addEventListener('keydown',event=>{
    if(modal.open||view!=='classic'||state.session.complete||event.repeat||event.ctrlKey||event.metaKey||event.altKey||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;
    if(event.key==='Enter'&&!['BUTTON','A'].includes(event.target.tagName)&&['feedback','showdown'].includes(current().play?.phase)){event.preventDefault();advance();return;}
    const n=Number(event.key);if(n>=1&&n<=4){const buttons=app.querySelectorAll('[data-do="play"]');if(buttons[n-1]){event.preventDefault();buttons[n-1].click();}}
  });
  modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
  window.addEventListener('pagehide',save);
  render();
})();
